55	async function api(path, body) {
56	  const resp = await fetch(path, body && {
57	    method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(body),
58	  });
59	  const data = await resp.json().catch(() => ({}));
60	  if (!resp.ok) throw new Error(typeof data.detail === "string" ? data.detail : JSON.stringify(data.detail ?? resp.statusText));
61	  return data;
62	}
