74	async function load() {
75	  const [nodes, edges] = await Promise.all([api("/nodes"), api("/edges")]);
76	  // polling during agent runs calls this every 1.5 s: only redraw when something changed
77	  const sig = nodes.map((n) => n.id + n.status).join() + edges.length;
78	  if (sig === load.sig) return;
79	  load.sig = sig;
80	  graph = { nodes, edges };
81	  view = derive(nodes, edges);
82	  render();
83	}
84	
85	function derive(nodes, edges) {
86	  const byId = Object.fromEntries(nodes.map((n) => [n.id, n]));
87	  const decisionsFor = {}, supersededBy = {}, inputs = {}, dependents = {};
88	  for (const e of edges) {
89	    (inputs[e.from_id] ??= []).push(e);
90	    // decisions show up as the target's verdict, not in its "Used by" list
91	    if (e.relation === "decides") (decisionsFor[e.to_id] ??= []).push(byId[e.from_id]);
92	    else (dependents[e.to_id] ??= []).push(e);
93	  }
94	  for (const n of nodes) if (n.replaces) supersededBy[n.replaces] = n.id;
95	  return { byId, decisionsFor, supersededBy, inputs, dependents };
96	}
