98	const summary = (n) => {
99	  const c = n.content || {};
100	  if (c.rows) return `${c.file ?? "file"} · ${c.rows.length} rows`;
101	  return String(c.text ?? c.quote ?? c.file ?? c.verdict ?? JSON.stringify(c));
102	};
103	const verdictOf = (id) => (view.decisionsFor[id] || []).at(-1)?.content?.verdict;
