105	// ---- graph -------------------------------------------------------------
106	
107	function render() {
108	  const drawn = graph.nodes.filter((n) => n.type in STAGE);
109	  const pos = layout(drawn, graph.edges);
110	  lastPos = pos;
111	  const grew = drawn.length > cy.nodes().length; // new nodes (e.g. mid agent run) must stay in view
112	  cy.elements().remove();
113	  cy.add(drawn.map((n) => ({
114	    group: "nodes",
115	    data: { id: n.id, type: n.type, label: `${n.id}${n.version > 1 ? ` v${n.version}` : ""}\n${short(summary(n), 70)}` },
116	    position: pos[n.id],
117	    classes: [n.status === "stale" && "stale", view.supersededBy[n.id] && "superseded", verdictOf(n.id),
118	      waitingOn(n) && "awaiting"].filter(Boolean).join(" "),
119	  })));
120	  const isDrawn = (id) => id in pos;
121	  // arrows follow the chain (input -> derived), except "X supports/contradicts Y", which points at Y
122	  const pointsAtInput = (e) => e.relation === "supports" || e.relation === "contradicts";
123	  cy.add(graph.edges.filter((e) => isDrawn(e.from_id) && isDrawn(e.to_id)).map((e, i) => ({
124	    group: "edges",
125	    data: { id: `e${i}`, source: pointsAtInput(e) ? e.from_id : e.to_id, target: pointsAtInput(e) ? e.to_id : e.from_id },
126	    classes: e.relation,
127	  })));
128	  cy.add(drawn.filter((n) => n.replaces && isDrawn(n.replaces)).map((n) => ({
129	    group: "edges", data: { id: `v-${n.id}`, source: n.replaces, target: n.id }, classes: "version",
130	  })));
131	  if (grew) {
132	    cy.fit(undefined, 40);
133	    if (cy.zoom() > 1) { cy.zoom(1); cy.center(); } // a 2-node graph shouldn't fill the screen
134	  }
135	
136	  $("#empty").hidden = graph.nodes.length > 0;
137	  renderStats();
138	  renderJump();
139	  if (draft || linking) markPicked(); // an open form must survive redraws (e.g. agent polling)
140	  else if (selected && view.byId[selected]) select(selected);
141	  else showHint();
142	  renderTimeline();
143	}
