242	    .map((e) => e.from_id);
243	  const reReview = decisions.length > 0 && (decisions.at(-1).status === "stale" || newerCounter(decisions.at(-1)).length > 0);
244	  const newer = view.supersededBy[n.id];
245	  const ins = view.inputs[n.id] || [];
246	  const deps = view.dependents[n.id] || [];
