275	        ${d.status === "stale" ? `<span class="warn"> · re-review: evidence changed</span>` : ""}
276	        ${newerCounter(d).length ? `<span class="warn"> · re-review: counter-evidence ${newerCounter(d).map((id) => chip(id)).join(" ")} came in after this</span>` : ""}
