298	// ---- audit timeline ----------------------------------------------------
299	// Every node is one audit entry (append-only graph = the audit trail, VISION.md write rule 2).
300	
301	let currentView = "graph";
302	
303	function setView(v) {
304	  currentView = v;
305	  for (const b of document.querySelectorAll("[data-view]")) b.setAttribute("aria-pressed", String(b.dataset.view === v));
306	  $("#graph").hidden = v !== "graph";
