313	/** Everything (transitively) built on id, including PM decisions on those nodes. */
314	function builtOn(id) {
315	  const seen = new Set();
316	  const todo = [id];
317	  while (todo.length) {
318	    const cur = todo.pop();
319	    const next = [...(view.dependents[cur] || []).map((e) => e.from_id), ...(view.decisionsFor[cur] || []).map((d) => d.id)];
320	    for (const d of next) if (!seen.has(d)) { seen.add(d); todo.push(d); }
321	  }
322	  return [...seen];
323	}
324	
325	/** One line saying what happened, in PM language. */
326	function describe(n) {
327	  const ins = view.inputs[n.id] || [];
328	  const ids = (rel) => ins.filter((e) => !rel || e.relation === rel).map((e) => chip(e.to_id)).join(" ");
329	  const request = n.content?.request;
330	  if (n.type === "Decision") return `<b>${esc(n.content?.verdict ?? "decided")}</b> ${ids()}`;
331	  if (n.replaces) {
332	    const old = view.byId[n.replaces];
333	    const sameContent = old && JSON.stringify(old.content) === JSON.stringify(n.content);
334	    const stale = builtOn(n.replaces).filter((id) => view.byId[id]?.status === "stale");
335	    return `${sameContent ? "connected a new input to" : "edited"} ${chip(n.replaces)} → v${n.version} ${chip(n.id)}`
336	      + (stale.length ? `<div class="why">now stale because of this: ${stale.map((id) => chip(id)).join(" ")}</div>` : "");
337	  }
338	  if (n.type === "Source") return `imported ${chip(n.id)}`;
339	  if (request) return `asked the agent to <b>${esc(REQUESTS[request])}</b> ${ids()} ${chip(n.id)}`;
340	  if (n.type === "Question") return `asked ${n.created_by.startsWith("PM:") ? "the agent" : "the PM"} ${chip(n.id)}${ins.length ? ` about ${ids()}` : ""}`;
341	  if (n.type === "Note" && ins.some((e) => view.byId[e.to_id]?.type === "Question")) return `answered ${ids()} with ${chip(n.id)}`;
342	  if (ins.some((e) => e.relation === "contradicts")) return `recorded counter-evidence ${chip(n.id)} against ${ids("contradicts")}`;
343	  if (n.type === "Score") return `scored ${ids()} → ${chip(n.id)}`;
344	  return `added ${esc(n.type)} ${chip(n.id)}${ins.length ? ` from ${ids()}` : ""}`;
345	}
