349	function renderTimeline() {
350	  if (currentView !== "timeline") return;
351	  const types = [...new Set(graph.nodes.map((n) => n.type))];
352	  const typeSel = $("#trailType");
353	  if (typeSel.options.length !== types.length + 1) {
354	    typeSel.innerHTML = `<option value="">all</option>` + types.map((t) => `<option>${esc(t)}</option>`).join("");
355	  }
356	  const actor = $("#trailActor").value;
357	  const type = typeSel.value;
358	  let chain = null;
359	  if ($("#trailChain").checked && selected) {
360	    const el = cy.getElementById(selected);
361	    chain = new Set([selected, ...(el.nonempty() ? el.predecessors().union(el.successors()).nodes().map((x) => x.id()) : [])]);
362	    for (const id of [...chain]) for (const d of view.decisionsFor[id] || []) chain.add(d.id);
363	  }
364	  const shown = graph.nodes.filter((n) =>
365	    (!actor || (actor === "other" ? actorClass(n.created_by) === "other" : n.created_by.startsWith(actor)))
366	    && (!type || n.type === type) && (!chain || chain.has(n.id))).reverse();
367	  $("#trail").innerHTML = shown.map((n) => `
368	    <li class="entry ${n.id === selected ? "current" : ""}" data-id="${esc(n.id)}">
369	      <time datetime="${esc(n.timestamp)}">${esc(new Date(n.timestamp).toLocaleString())}</time>
370	      <span class="actor ${actorClass(n.created_by)}">${esc(n.created_by)}</span>
371	      <div class="body">
372	        <div>${describe(n)}</div>
373	        ${n.type === "Decision" ? "" : `<div class="text">${esc(short(summary(n), 160))}</div>`}
374	        ${n.rationale ? `<div class="why">Why: ${esc(n.rationale)}</div>` : ""}
375	      </div>
376	    </li>`).join("") || `<li class="meta">Nothing matches these filters.</li>`;
