410	// ---- composing: new nodes + connections ---------------------------------
411	
412	const CREATABLE = ["Source", "Evidence", "Claim", "Assumption", "Requirement", "Question", "Note"];
413	const NO_INPUTS = new Set(["Source", "Question", "Note"]); // backend rule: everything else needs inputs
414	const NEXT = { // what a PM typically builds on a node of this type (right-click menu)
415	  Source: ["Evidence"], Evidence: ["Claim"], Claim: ["Requirement", "Assumption"],
416	  Assumption: ["Requirement"], Note: ["Claim"],
417	};
418	const REQUESTS = { challenge: "challenge", dig_deeper: "dig deeper" };
419	const requestDraft = (id, request) => openDraft("Question", [id], {
420	  request,
421	  text: request === "challenge"
422	    ? `Challenge ${id}: look for evidence against it in the sources.`
423	    : `Dig deeper on ${id}: find more, different evidence about it.`,
424	});
425	
426	// The agent-loop's handled() rule, mirrored: a PM Question/Note is done once the agent built
427	// on it, or — for "challenge" — once the agent built on its target after it was asked.
428	function pmInputDoneBy(n) {
429	  const agentDeps = (id) => (view.dependents[id] || []).map((e) => view.byId[e.from_id])
430	    .filter((d) => d.created_by.startsWith("agent:"));
431	  const own = agentDeps(n.id)[0];
432	  if (own || n.content?.request !== "challenge") return own?.id;
433	  return (view.inputs[n.id] || []).flatMap((e) => agentDeps(e.to_id))
434	    .find((d) => new Date(d.timestamp) > new Date(n.timestamp))?.id;
435	}
436	
437	/** Who has to act: "agent" (open PM input), "pm" (unanswered agent question), else null. */
438	function waitingOn(n) {
439	  if (!["Question", "Note"].includes(n.type)) return null;
440	  if (n.created_by.startsWith("PM:")) return pmInputDoneBy(n) ? null : "agent";
441	  return n.type === "Question" && !(view.dependents[n.id] || []).length ? "pm" : null;
442	}
