471	    <p class="meta">${request ? "The next agent run handles this before anything else. " : ""}
472	      ${NO_INPUTS.has(type) ? "Inputs are optional." : "Needs at least one input."}
473	      Click nodes in the graph to add or remove inputs. It appears in the ${esc(type)} column.</p>
474	    <div class="actions">
475	      <label for="draftText">Text</label>
476	      <textarea id="draftText" rows="3">${esc(text)}</textarea>
477	      <h3>Built on</h3>
