479	      <label>Add input <select id="draftPick">${nodeOptions()}</select></label>
480	      ${type === "Source" ? "" : `<label>Relation to its inputs <select id="draftRel">
481	        <option value="derived_from">derived from</option><option value="supports">supports</option>
482	        <option value="contradicts">contradicts (counter-evidence)</option></select></label>`}
483	      <label for="reason">Why (rationale, optional)</label>
484	      <textarea id="reason"></textarea>
