493	function renderDraftInputs() {
494	  $("#draftInputs").innerHTML = draft.inputs.map((id) =>
495	    `<button type="button" class="chip" data-unpick="${esc(id)}" aria-label="Remove input ${esc(id)}">${esc(id)} ✕</button>`,
496	  ).join("") || `<span class="meta">nothing yet</span>`;
497	  markPicked();
