505	async function createNode() {
506	  const text = $("#draftText").value.trim();
507	  if (!text) throw new Error("Write the node's text first.");
508	  const created = await api("/nodes", {
509	    type: draft.type, content: draft.request ? { text, request: draft.request } : { text },
510	    inputs: draft.inputs, created_by: pmName(), rationale: $("#reason").value.trim() || null,
511	    relation: draft.relation,
512	  });
513	  toast(draft.request ? `${created.id} created — Run agent to have it handled` : `${created.id} created`);
514	  draft = null;
515	  selected = created.id;
516	  await load();
517	}
