526	function renderLink() {
527	  const { from, to } = linking;
528	  const target = to && view.byId[to];
529	  const end = (id) => (id ? `<b>${esc(id)}</b>` : `<i>click a node</i>`);
530	  $("#detail").innerHTML = `
531	    <h2>Connect</h2>
532	    <div class="actions">
533	      <p>${end(from)} becomes an input of ${end(to)}</p>
534	      ${from && to ? `
535	        <p class="meta">Edges are permanent and only written together with a node, so this writes
536	          ${esc(to)} v${target.version + 1} with the extra input; v${target.version} and everything
537	          built on it turn stale.</p>
538	        <label for="reason">Why connect them? (audit trail)</label>
539	        <textarea id="reason"></textarea>` : `<p class="hint">Click the missing node in the graph. Esc cancels.</p>`}
540	      <div class="row">
541	        ${from && to ? `<button type="button" id="doLink" class="primary">Connect</button>
542	          <button type="button" id="swapLink">Swap direction</button>` : ""}
543	        <button type="button" id="cancelMode">Cancel</button>
544	      </div>
545	    </div>`;
546	  markPicked();
547	}
548	
549	function pickLinkEnd(id) {
550	  if (!linking.from) linking.from = id;
551	  else linking.to = id;
552	  renderLink();
553	}
554	
555	async function doLink() {
556	  const target = view.byId[linking.to];
557	  const created = await api("/edit", {
558	    content: target.content, target_id: target.id, created_by: pmName(), rationale: reason(),
559	    add_inputs: [linking.from],
560	  });
561	  toast(`${linking.from} connected: ${target.id} → ${created.id} (v${created.version})`);
562	  linking = null;
563	  selected = created.id;
564	  await load();
565	}
