582	function nodeMenu(id) {
583	  const n = view.byId[id];
584	  return [
585	    ...(waitingOn(n) === "pm" ? [{ label: `Answer ${id}`, run: () => openDraft("Note", [id]) }] : []),
586	    ...(NEXT[n.type] || []).map((t) => ({ label: `New ${t} from ${id}`, run: () => openDraft(t, [id]) })),
587	    { label: `Ask the agent to challenge ${id}`, run: () => requestDraft(id, "challenge") },
588	    { label: `Ask the agent to dig deeper on ${id}`, run: () => requestDraft(id, "dig_deeper") },
589	    { label: `Supporting evidence for ${id}`, run: () => openDraft("Evidence", [id], { relation: "supports" }) },
590	    { label: `Counter-evidence for ${id} (by hand)`, run: () => openDraft("Evidence", [id], { relation: "contradicts" }) },
591	    { label: `Ask a question about ${id}`, run: () => openDraft("Question", [id]) },
592	    { label: `Add a note to ${id}`, run: () => openDraft("Note", [id]) },
593	    ...(view.supersededBy[id] ? [] : [{ label: `Connect: add an input to ${id}…`, run: () => openLink(null, id) }]),
594	    { label: `Connect: use ${id} as an input of…`, run: () => openLink(id, null) },
595	  ];
596	}
