598	const inside = (b, x, y) => x >= b.x1 && x <= b.x2 && y >= b.y1 && y <= b.y2;
599	const nodeAt = (x, y, except = null) => cy.nodes().filter((n) => n.id() !== except && inside(n.renderedBoundingBox(), x, y))[0];
