610	function showAgent(st) {
611	  $("#run").disabled = st.running;
612	  const state = st.running ? "running…" : st.exit_code == null ? "idle"
613	    : st.exit_code === 0 ? "last run finished" : `last run failed (exit ${st.exit_code}), see log`;
614	  $("#agentStatus").textContent = `Agent: ${state} · ${st.llm ? "LLM" : "rule-based (no OPENAI_API_KEY on the backend)"}`;
