623	function poll() {
624	  clearTimeout(poll.timer);
625	  poll.timer = setTimeout(guard(async () => {
626	    const st = await api("/agent/status");
627	    showAgent(st);
628	    await load();
629	    if (st.running) poll();
630	    else toast(st.exit_code === 0 ? "Agent run finished" : `Agent run failed (exit ${st.exit_code}), see log`, st.exit_code !== 0);
631	  }), 1500);
632	}
