634	const guard = (fn) => (...args) => Promise.resolve().then(() => fn(...args)).catch((e) => toast(e.message, true));
635	
636	$("#detail").addEventListener("click", guard(async (ev) => {
637	  const t = ev.target.closest("button");
638	  if (!t) return;
639	  if (t.dataset.goto) select(t.dataset.goto);
640	  else if (t.dataset.verdict) await decide(t.dataset.verdict);
641	  else if (t.dataset.unpick) togglePick(t.dataset.unpick);
642	  else if (t.dataset.request) requestDraft(selected, t.dataset.request);
643	  else if (t.dataset.answer) openDraft("Note", [t.dataset.answer]);
644	  else if (t.id === "saveEdit") await saveEdit();
645	  else if (t.id === "createNode") await createNode();
646	  else if (t.id === "doLink") await doLink();
647	  else if (t.id === "swapLink") { linking = { from: linking.to, to: linking.from }; renderLink(); }
648	  else if (t.id === "cancelMode") closeModes();
649	}));
650	$("#detail").addEventListener("change", (ev) => {
651	  const { id, value } = ev.target;
652	  if (id === "draftPick" && value) { togglePick(value); ev.target.value = ""; }
653	  else if (id === "draftRel") draft.relation = value;
654	  else if (id === "addInput" && value) openLink(value, selected);
