671	    ? CREATABLE.map((t) => ({ label: `New ${t}`, run: () => openDraft(t) }))
672	    : nodeMenu(ev.target.id()));
673	});
674	// drag a node onto another to connect them; the earlier stage of the chain becomes the input
675	cy.on("dragfree", "node", (ev) => {
