732	pm.addEventListener("change", () => { try { localStorage.setItem("pmName", pm.value.trim()); } catch { /* ignore */ } });
733	
734	selected = decodeURIComponent(location.hash.slice(1)) || null;
735	guard(load)();
736	guard(async () => { // a run may already be going (page reloaded mid-run)
